insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2016c8a-bb00-46b1-8a8d-c78bcb62decf', 'de', 'Warum geht es beim Flirten oft nach hinten los, wenn du aufs Ergebnis fixiert bist?', '["Gespräche werden kürzer", "Es bremst den nächsten Schritt", "Es schwächt dein Selbstbewusstsein", "Es erzeugt Druck und Hintergedanken"]'::jsonb, 'Konzentrier dich darauf, das Gespräch verspielt zu machen, statt ein bestimmtes Ergebnis erreichen zu wollen.')
