insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90e66462-8fdd-4fa4-a574-bda55becad8c', 'de', 'Woran erkennst du, ob du weiterflirten solltest?', '["Deinem Bauchgefühl zur Stimmung vertrauen", "Darauf achten, wie sie reagiert, nicht wie du dich fühlst", "Auf ausdrückliche Worte achten, dass sie Interesse hat", "Einschätzen, ob ihr schon lange genug redet"]'::jsonb, 'Achte darauf, wie sie reagiert und wie sehr sie sich einbringt, nicht darauf, wie du dich fühlst.')
