insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fed7fe50-0325-493e-8647-62755e05fab5', 'de', 'Was gehört zum respektvollen Verhalten als Grundlage?', '["Ihre Signale lesen und respektieren", "Eine Abfuhr annehmen, ohne ihr ein schlechtes Gewissen zu machen oder pampig zu werden", "Sie nie ohne klare Zeichen berühren, dass es für sie okay ist", "Es noch mal versuchen, wenn du denkst, sie ist vielleicht schüchtern"]'::jsonb, 'Ein Flirt bleibt respektvoll, wenn dir ihr Wohlgefühl wichtiger ist als dein Erfolg.')
