insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3ec5acd-f47b-4bb8-bf22-81d9b16edd73', 'de', 'Eine entspannte Gruppe unterhält sich ruhig. Wie sollte deine Energie sein?', '["Voller Energie, um aufzufallen", "Etwas entspannter als sie", "Passend zu ihrem Tempo oder etwas darüber", "Still und zurückhaltend"]'::jsonb, 'Wenn du dich ihrem Ton anpasst, bleibt die Stimmung angenehm und gemeinsam.')
