insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50f09b6c-abae-46f2-a825-8acf3d58107e', 'de', 'Was schafft gute Energie?', '["Menschen fühlen sich leichter und lebendiger", "Sie lädt ein, sich zu öffnen und mitzuspielen", "Sie zeigt soziales Selbstbewusstsein und Charisma", "Sie schafft den Rahmen, in dem Flirten möglich wird"]'::jsonb, 'Gute Energie schafft Sicherheit und Verspieltheit, und so kann ganz natürlich ein Flirt entstehen.')
