insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8150d416-c806-4f77-898e-1532d0bc733f', 'de', 'Was solltest du beim Necken vermeiden?', '["Etwas übertreiben, worauf sie stolz zu sein scheint", "Ein lockeres Hin und Her", "Verspielt infrage stellen, was sie gesagt hat", "Themen, bei denen sie vielleicht unsicher ist"]'::jsonb, 'Necken funktioniert, wenn es Spaß macht und nicht verletzen kann.')
