insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e5a0bc4-d01b-4f85-9404-749642fa56b6', 'de', 'Bei welchen Themen kannst du sie ohne Risiko necken?', '["Ihr Aussehen", "Ihr Ehrgeiz", "Dass sie übertrieben ordentlich ist", "Dass sie schlecht kocht"]'::jsonb, 'Neck sie mit Eigenschaften, die harmlos sind und nichts mit Unsicherheiten zu tun haben.')
