insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('41b88925-4d87-4998-bcfb-64846e12bd89', 'de', 'Warum hilft etwas Frechheit beim Flirten?', '["Sie durchbricht übertrieben zustimmende Muster", "Sie zeigt Selbstbewusstsein mit Wärme", "Sie schafft verspielte Spannung und Rhythmus", "Sie setzt ernsthaften Widerspruch voraus"]'::jsonb, 'Leichter Widerspruch durchbricht die Eintönigkeit, schafft verspielte Spannung und hält die Energie lebendig.')
