insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('73e2048d-c6ed-4778-ac5a-699f953efb85', 'de', 'Welches Kompliment schafft am ehesten eine Verbindung?', '["„Du bist wirklich wunderschön.“", "„Du hast tolle Augen.“", "„Du bekommst bestimmt ständig Komplimente.“", "„Ich mag, wie du Dinge erklärst.“"]'::jsonb, 'Komplimente kommen am besten an, wenn sie etwas würdigen, das sie selbst gewählt hat, nicht ihre Merkmale.')
